const fallback={company:{whatsapp:'5579998371420'},gallery:[]};
let content=fallback;
try { const response=await fetch('./content.json'); if(!response.ok)throw Error('Conteúdo indisponível'); content=await response.json(); }catch(error){console.warn('Usando contato padrão.',error.message);}
const message=service=>`Olá, Cold Tech! Gostaria de atendimento${service?` para ${service}`:''}.`;
const whatsapp=text=>`https://wa.me/${content.company.whatsapp}?text=${encodeURIComponent(text)}`;
document.querySelectorAll('[data-whatsapp]').forEach(a=>{a.href=whatsapp(message(a.dataset.service));a.target='_blank';a.rel='noopener noreferrer';});
for(const item of content.gallery){const a=document.createElement('a');a.href=item.url;a.target='_blank';a.rel='noopener noreferrer';const figure=document.createElement('figure');const img=document.createElement('img');img.src=item.image;img.alt=item.alt;img.loading='lazy';img.width=640;img.height=742;const caption=document.createElement('figcaption');caption.textContent=item.title;figure.append(img,caption);a.append(figure);document.querySelector('#gallery').append(a);}
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}});
document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#quote').addEventListener('submit',e=>{e.preventDefault();const equipment=document.querySelector('#equipment').value,problem=document.querySelector('#problem').value.trim();window.open(whatsapp(`Olá, Cold Tech! Gostaria de atendimento.\nEquipamento: ${equipment}${problem?`\nProblema: ${problem}`:''}`),'_blank','noopener,noreferrer');});

for(const item of content.partners||[]){const figure=document.createElement('figure');figure.className='partner';const frame=document.createElement('div');frame.className='partner-logo';const [x,y,w,h]=item.region;const viewport=document.createElement('div');viewport.className='partner-crop';viewport.style.aspectRatio=`${w}/${h}`;const img=document.createElement('img');img.src=item.logo;img.alt=`Logo ${item.name}`;img.loading='lazy';img.style.width=`${882/w*100}%`;img.style.left=`${-x/w*100}%`;img.style.top=`${-y/h*100}%`;const caption=document.createElement('figcaption');caption.textContent=item.name;viewport.append(img);frame.append(viewport);figure.append(frame,caption);document.querySelector('#partners-grid').append(figure);}
